INSERT IGNORE INTO cms_content (content_key, title, body, section, is_published, updated_by) VALUES
 ('home.hero.title', 'A better lunch break starts here.', 'Discover food from campus vendors, order ahead, and pick it up when it is ready.', 'hero', 1, 1),
 ('home.hero.note', 'Good food, right around campus.', 'Browse without an account. Sign in only when you are ready to order.', 'hero', 1, 1),
 ('announcement.welcome', 'Lunch orders are open', 'Order ahead from campus vendors. Payment is cash at pickup.', 'announcement', 1, 1),
 ('page.about', 'About CampusBite', 'CampusBite helps students discover campus food, order ahead, and pick up without missing the next class.', 'page', 1, 1),
 ('page.help', 'Help', 'Browse foods without signing in. To place an order, create a student account, add items from one vendor, and pay cash when you pick up. Check My orders for status updates.', 'page', 1, 1),
 ('page.contact', 'Contact', 'For help with an order, contact the vendor shown on your order. For account or site issues, speak with your campus administrator.', 'page', 1, 1),
 ('page.terms', 'Terms of use', 'CampusBite is a campus ordering tool. Orders are paid in cash at pickup. Confirm details with the vendor if you have an allergy or a special request.', 'page', 1, 1),
 ('page.privacy', 'Privacy', 'CampusBite stores account and order information in the campus database. Access is limited by account role and used to operate the ordering service.', 'page', 1, 1);

